16	// NewReviewer returns the AgentReviewer for codex.
17	//
18	// Argv shape: codex exec --skip-git-repo-check -.
19	// Prompt is piped via stdin (the trailing "-" tells codex to read from stdin).
20	// Stdout includes chrome (banners, hook notices, exec blocks, CSI sequences)
21	// that output_filter.go strips before emitting AssistantText events.
22	func NewReviewer() *reviewtypes.ReviewerTemplate {
23		return &reviewtypes.ReviewerTemplate{
24			AgentName: "codex",
25			BuildCmd:  buildCodexReviewCmd,
26			Parser:    parseCodexOutput,
27		}
28	}
29	
30	// buildCodexReviewCmd builds the exec.Cmd for a codex review run.
31	// Exposed at package level for test inspection of argv, stdin, and env.
32	func buildCodexReviewCmd(ctx context.Context, cfg reviewtypes.RunConfig) *exec.Cmd {
33		promptCfg := cfg
34		promptCfg.Skills = expandCodexBuiltinReview(cfg.Skills)
35		args := []string{codexExecCommand, "--skip-git-repo-check", "-"}
36		prompt := review.ComposeReviewPrompt(promptCfg)
37		cmd := exec.CommandContext(ctx, "codex", args...)
38		cmd.Stdin = strings.NewReader(prompt)
39		cmd.Env = review.AppendReviewEnv(os.Environ(), "codex", cfg, prompt)
40		return cmd
41	}
42	
43	// Codex's native `exec review --base <branch>` rejects an additional prompt,
44	// so expand `/review` into text and run normal `codex exec -`. That preserves
45	// Entire's scoped base clause, per-run instructions, and checkpoint context.
46	const codexBuiltinReviewPrompt = "Review the current branch changes and report actionable findings. " +
47		"Prioritize correctness, regressions, security, and missing test coverage. Do not make code changes."
48	
49	const codexExecCommand = "exec"
50	
51	func expandCodexBuiltinReview(skills []string) []string {
52		out := make([]string, 0, len(skills))
53		for _, skill := range skills {
54			if skill == "/review" {
55				out = append(out, codexBuiltinReviewPrompt)
56				continue
57			}
58			out = append(out, skill)
59		}
60		return out
61	}
62	
63	// parseCodexOutput wraps the reader with the chrome filter and converts
64	// remaining lines into a stream of Events.
65	// On clean EOF emits Finished{Success: true}. On a scanner error (including
66	// errors propagated from Strip via pipe CloseWithError) emits RunError then
67	// Finished{Success: false}.
68	//
69	// Exposed for golden-file contract testing.
70	func parseCodexOutput(r io.Reader) <-chan reviewtypes.Event {
71		out := make(chan reviewtypes.Event, 32)
72		go func() {
73			defer close(out)
74			out <- reviewtypes.Started{}
75			scanner := bufio.NewScanner(r)
76			scanner.Buffer(make([]byte, 1024*1024), 16*1024*1024)
77			state := codexEventNormal
78			for scanner.Scan() {
79				for _, ev := range collectCodexEventsLine(scanner.Text(), &state) {
80					out <- ev
81				}
82			}
83			if err := scanner.Err(); err != nil {
84				out <- reviewtypes.RunError{Err: fmt.Errorf("read stdout: %w", err)}
85				out <- reviewtypes.Finished{Success: false}
86				return
87			}
88			out <- reviewtypes.Finished{Success: true}
89		}()
90		return out
91	}
92	
93	type codexEventState int
94	
95	const (
96		codexEventNormal codexEventState = iota
97		codexEventUserBlock
98		codexEventAssistantBlock
99		codexEventExecAwaitCommand
100		codexEventExecBlock
101		codexEventAfterTokens
102	)
103	
104	func collectCodexEventsLine(raw string, state *codexEventState) []reviewtypes.Event {
105		cleaned := csiRegex.ReplaceAllString(raw, "")
106		trimmed := strings.TrimSpace(cleaned)
107		trimmedRight := strings.TrimRight(cleaned, " \t")
108	
109		if *state == codexEventAfterTokens {
110			return nil
111		}
112		if isTokensUsedMarker(trimmed) {
113			*state = codexEventAfterTokens
114			return nil
115		}
116	
117		switch *state {
118		case codexEventUserBlock:
119			if isCodexRoleMarker(trimmed) {
120				*state = codexEventAssistantBlock
121			}
122			return nil
123		case codexEventAssistantBlock:
124			return collectCodexAssistantLine(raw, trimmed, trimmedRight, state)
125		case codexEventExecAwaitCommand:
126			return collectCodexExecCommandLine(trimmed, trimmedRight, state)
127		case codexEventExecBlock:
128			switch {
129			case trimmed == "":
130				*state = codexEventNormal
131			case isCodexRoleMarker(trimmed):
132				*state = codexEventAssistantBlock
133			case isUserRoleMarker(trimmed):
134				*state = codexEventUserBlock
135			}
136			return nil
137		case codexEventNormal:
138			// Continue below.
139		case codexEventAfterTokens:
140			return nil
141		}
142	
143		if isUserRoleMarker(trimmed) {
144			*state = codexEventUserBlock
145			return nil
146		}
147		if isCodexRoleMarker(trimmed) {
148			*state = codexEventAssistantBlock
149			return nil
150		}
151		if isCodexMetadataLine(trimmed) {
152			return nil
153		}
154		if trimmedRight == codexExecCommand {
155			*state = codexEventExecAwaitCommand
156			return nil
157		}
158		if execBlockRegex.MatchString(trimmedRight) {
159			*state = codexEventExecBlock
160			return []reviewtypes.Event{reviewtypes.ToolCall{Name: codexExecCommand, Args: trimmedRight}}
161		}
162		if line, ok := FilterLine(raw); ok {
163			return []reviewtypes.Event{reviewtypes.AssistantText{Text: line}}
164		}
165		return nil
166	}
167	
168	func collectCodexAssistantLine(raw, trimmed, trimmedRight string, state *codexEventState) []reviewtypes.Event {
169		switch {
170		case isCodexRoleMarker(trimmed):
171			return nil
172		case isUserRoleMarker(trimmed):
173			*state = codexEventUserBlock
174			return nil
175		case trimmedRight == codexExecCommand:
176			*state = codexEventExecAwaitCommand
177			return nil
178		case execBlockRegex.MatchString(trimmedRight):
179			*state = codexEventExecBlock
180			return []reviewtypes.Event{reviewtypes.ToolCall{Name: codexExecCommand, Args: trimmedRight}}
181		case isCodexMetadataLine(trimmed):
182			return nil
183		default:
184			if line, ok := FilterLine(raw); ok {
185				return []reviewtypes.Event{reviewtypes.AssistantText{Text: line}}
186			}
187			return nil
188		}
189	}
190	
191	func collectCodexExecCommandLine(trimmed, trimmedRight string, state *codexEventState) []reviewtypes.Event {
192		switch {
193		case trimmed == "":
194			*state = codexEventNormal
195			return nil
196		case isCodexRoleMarker(trimmed):
197			*state = codexEventAssistantBlock
198			return nil
199		case isUserRoleMarker(trimmed):
200			*state = codexEventUserBlock
201			return nil
202		default:
203			*state = codexEventExecBlock
204			return []reviewtypes.Event{reviewtypes.ToolCall{Name: codexExecCommand, Args: trimmedRight}}
205		}
206	}
