1	// Package review — see env.go for package-level rationale.
2	//
3	// picker.go implements the interactive review skills picker and agent selection
4	// helpers. pickConfig presents a huh multi-select per installed agent and saves
5	// the selection to .entire/settings.json.
6	package review
7	
8	import (
9		"context"
10		"errors"
11		"fmt"
12		"io"
13		"log/slog"
14		"os"
15		"sort"
16		"strings"
17	
18		"charm.land/huh/v2"
19	
20		"github.com/entireio/cli/cmd/entire/cli/agent"
21		"github.com/entireio/cli/cmd/entire/cli/agent/skilldiscovery"
22		"github.com/entireio/cli/cmd/entire/cli/agent/types"
23		"github.com/entireio/cli/cmd/entire/cli/logging"
24		reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
25		"github.com/entireio/cli/cmd/entire/cli/settings"
26	)
27	
28	// AgentChoice is one row in the spawn-time picker. Name is the agent
29	// registry key (used for marker/override); Label is the picker-visible
30	// string ("<name>   (N skills configured)" or "<name>   (prompt-only)").
31	type AgentChoice struct {
32		Name  string
33		Label string
34	}
35	
36	// newAccessibleForm creates a huh form with accessibility mode enabled when
37	// the ACCESSIBLE env var is set. Mirrors cli.NewAccessibleForm without
38	// requiring an import of the cli package (which would be circular).
39	func newAccessibleForm(groups ...*huh.Group) *huh.Form {
40		form := huh.NewForm(groups...).WithTheme(huh.ThemeFunc(huh.ThemeDracula))
41		if os.Getenv("ACCESSIBLE") != "" {
42			form = form.WithAccessible(true)
43		}
44		return form
45	}
46	
47	// ConfirmFirstRunSetup prints a banner framing the picker as first-run
48	// setup (rather than the review itself) and waits for the user to confirm.
49	// Returns false if the user cancels; caller should bail gracefully.
50	//
51	// Signposting matters here because `entire review` with no config silently
52	// drops into the picker — users running the command to start a review can
53	// mistake the picker for the review. The banner + confirmation makes the
54	// setup phase explicit, and the trailing "running review now" line in the
55	// caller closes the loop on what comes next.
56	func ConfirmFirstRunSetup(ctx context.Context, out io.Writer) bool {
57		fmt.Fprintln(out, "No review config found — let's set one up first.")
58		fmt.Fprintln(out)
59		fmt.Fprintln(out, "You'll pick skills for each installed agent. They're saved to")
60		fmt.Fprintln(out, ".entire/settings.json; edit later with `entire review --edit`.")
61		fmt.Fprintln(out, "After setup, the review will run with your selection.")
62		fmt.Fprintln(out)
63	
64		proceed := true
65		form := newAccessibleForm(huh.NewGroup(
66			huh.NewConfirm().
67				Title("Set up review skills now?").
68				Affirmative("Yes").
69				Negative("Cancel").
70				Value(&proceed),
71		))
72		if err := form.RunWithContext(ctx); err != nil {
73			fmt.Fprintln(out, "Setup cancelled.")
74			return false
75		}
76		if !proceed {
77			fmt.Fprintln(out, "Setup cancelled.")
78		}
79		return proceed
80	}
81	
82	// RunReviewConfigPicker presents a huh multi-select for each installed agent
83	// that has curated review skills, and saves the selection to
84	// .entire/settings.json. Previously-saved skills are pre-checked via
85	// huh.Option.Selected(true), mirroring how `entire enable` preserves prior
86	// selections in its own agent picker.
87	//
88	// getInstalled is injected to avoid an import cycle with the cli package.
89	func RunReviewConfigPicker(ctx context.Context, out io.Writer, getInstalled func(context.Context) []types.AgentName) (map[string]settings.ReviewConfig, error) {
90		installed := getInstalled(ctx)
91		if len(installed) == 0 {
92			return nil, errors.New(
93				"no agents with hooks installed; " +
94					"run 'entire configure --agent <name>' to install hooks for one, " +
95					"or 'entire enable' to set up the repo",
96			)
97		}
98	
99		// Narrow to agents that have a curated skills list; others need manual
100		// editing of settings.json under review.<agent-name>.
101		type configurableAgent struct {
102			name types.AgentName
103			ag   agent.Agent
104		}
105		var configurable []configurableAgent
106		for _, name := range installed {
107			if !skilldiscovery.IsEligible(string(name)) {
108				continue
109			}
110			ag, err := agent.Get(name)
111			if err != nil {
112				continue
113			}
114			configurable = append(configurable, configurableAgent{name: name, ag: ag})
115		}
116		if len(configurable) == 0 {
117			return nil, errors.New(
118				"no installed agents have curated review skills; " +
119					"edit .entire/settings.json directly under review.<agent-name>",
120			)
121		}
122	
123		// Load existing config so we can pre-check saved skills and seed saved
124		// prompts. A load error here means the settings file is malformed; log
125		// at Warn so users debugging "my saved skills aren't pre-checked" can
126		// see why, but keep going with an empty prefill — runReview already
127		// surfaces the same error distinctly when it's the first load.
128		existing := map[string]settings.ReviewConfig{}
129		existingFixAgent := ""
130		if s, err := settings.Load(ctx); err != nil {
131			logging.Warn(ctx, "settings.Load failed when pre-filling picker", slog.String("error", err.Error()))
132		} else if s != nil {
133			existing = s.Review
134			existingFixAgent = s.ReviewFixAgent
135		}
136	
137		// Up-front header: make the order and count obvious so users can spot
138		// when an agent they expected isn't being offered (e.g., hooks not
139		// installed for it yet).
140		labels := make([]string, 0, len(configurable))
141		for _, c := range configurable {
142			labels = append(labels, string(c.ag.Type()))
143		}
144		fmt.Fprintf(out, "Configuring review for %d agent(s): %s\n", len(configurable), strings.Join(labels, ", "))
145		fmt.Fprintln(out, "(Previously-saved skills are pre-checked. Space to toggle, enter to confirm.)")
146		fmt.Fprintln(out)
147	
148		selected := map[string]settings.ReviewConfig{}
149		for i, c := range configurable {
150			curated := skilldiscovery.CuratedBuiltinsFor(string(c.name))
151	
152			// Discover + dedupe + filter hints.
153			var discovered []agent.DiscoveredSkill
154			if d, ok := c.ag.(agent.SkillDiscoverer); ok {
155				if ds, dErr := d.DiscoverReviewSkills(ctx); dErr == nil {
156					discovered = ds
157				} else {
158					logging.Debug(ctx, "review discovery failed",
159						slog.String("agent", string(c.name)), slog.String("error", dErr.Error()))
160				}
161			}
162			builtinNames := builtinNameSet(curated)
163			discovered = filterOutBuiltinCollisions(discovered, builtinNames)
164	
165			discoveredSet := make(map[string]struct{}, len(discovered))
166			for _, d := range discovered {
167				discoveredSet[d.Name] = struct{}{}
168			}
169			activeHints := skilldiscovery.ActiveInstallHintsFor(string(c.name), discoveredSet)
170	
171			// Pre-populate pick slices from saved config so the picker preselects
172			// them. The header promises "previously-saved skills are pre-checked";
173			// without this split + Option.Selected(true) in BuildReviewPickerFields,
174			// --edit with accept-defaults silently wipes the agent's saved skills.
175			builtinPicks, discoveredPicks := SplitSavedPicks(
176				existing[string(c.name)].Skills, curated, discovered,
177			)
178			prompt := existing[string(c.name)].Prompt
179	
180			fields := BuildReviewPickerFields(
181				string(c.name), curated, discovered, activeHints, prompt,
182				&builtinPicks, &discoveredPicks, &prompt,
183			)
184	
185			// Prepend a non-blocking header Note so the agent being configured
186			// is always clearly visible.
187			header := huh.NewNote().
188				Title(string(c.ag.Type())).
189				Description(fmt.Sprintf("Agent %d of %d · pick review skills and optional instructions", i+1, len(configurable)))
190			fields = append([]huh.Field{header}, fields...)
191	
192			form := newAccessibleForm(huh.NewGroup(fields...))
193			if err := form.RunWithContext(ctx); err != nil {
194				return nil, fmt.Errorf("picker for %s: %w", c.name, err)
195			}
196	
197			cfg := settings.ReviewConfig{
198				Skills: dedupeStrings(append(builtinPicks, discoveredPicks...)),
199				Prompt: strings.TrimSpace(prompt),
200			}
201			if !cfg.IsZero() {
202				selected[string(c.name)] = cfg
203			}
204		}
205		// Merge the picker's output with existing entries the picker could not
206		// surface. Without the merge, save would replace s.Review wholesale and
207		// silently drop entries the user had configured for external agents,
208		// uncurated agents, or agents whose hooks are temporarily uninstalled.
209		offered := make(map[string]struct{}, len(configurable))
210		for _, c := range configurable {
211			offered[string(c.name)] = struct{}{}
212		}
213		merged := MergePickerResults(existing, offered, selected)
214	
215		// The emptiness check runs on `merged`, not `selected`.
216		if len(merged) == 0 {
217			return nil, errors.New("no review skills or prompt configured")
218		}
219	
220		fixAgent, err := pickReviewFixAgentPreference(ctx, merged, existingFixAgent)
221		if err != nil {
222			return nil, err
223		}
224		if err := saveReviewConfigAndFixAgent(ctx, merged, fixAgent); err != nil {
225			return nil, err
226		}
227		fmt.Fprintln(out, "Saved review config to .entire/settings.json. Edit directly or run `entire review --edit`.")
228		return merged, nil
229	}
