231	// MergePickerResults combines the picker's output with existing review
232	// config entries that the picker did not surface. Agents in `offered` are
233	// fully controlled by the picker: if they appear in `selected` with a
234	// non-zero config the entry is set, otherwise the entry is removed.
235	// Agents not in `offered` keep their existing config untouched.
236	//
237	// Exported so tests can drive it directly — the picker itself
238	// can't run headless.
239	func MergePickerResults(existing map[string]settings.ReviewConfig, offered map[string]struct{}, selected map[string]settings.ReviewConfig) map[string]settings.ReviewConfig {
240		merged := make(map[string]settings.ReviewConfig, len(existing)+len(selected))
241		for name, cfg := range existing {
242			if _, wasOffered := offered[name]; !wasOffered {
243				merged[name] = cfg
244			}
245		}
246		for name, cfg := range selected {
247			merged[name] = cfg
248		}
249		return merged
250	}
