252	// SaveReviewConfig persists the review map into .entire/settings.json while
253	// preserving all other settings. A Load error means the file exists but is
254	// malformed — we must NOT silently overwrite it with an empty struct, or
255	// every unrelated setting the user had configured would be wiped. Return the
256	// error so the caller can surface it instead.
257	func SaveReviewConfig(ctx context.Context, review map[string]settings.ReviewConfig) error {
258		s, err := settings.Load(ctx)
259		if err != nil {
260			return fmt.Errorf("load settings before save: %w", err)
261		}
262		if s == nil {
263			s = &settings.EntireSettings{}
264		}
265		s.Review = review
266		if err := settings.Save(ctx, s); err != nil {
267			return fmt.Errorf("save settings: %w", err)
268		}
269		return nil
270	}
