315	// ComputeEligibleConfigured returns the sorted list of agents that are both
316	// configured (non-zero ReviewConfig entry) AND have hooks installed. Only
317	// eligible agents are valid picker targets — spawning a review for an agent
318	// without hooks would silently drop the review metadata.
319	func ComputeEligibleConfigured(s *settings.EntireSettings, installed []types.AgentName) []AgentChoice {
320		if s == nil {
321			return nil
322		}
323		installedSet := make(map[types.AgentName]struct{}, len(installed))
324		for _, name := range installed {
325			installedSet[name] = struct{}{}
326		}
327		out := make([]AgentChoice, 0, len(s.Review))
328		for name, cfg := range s.Review {
329			if cfg.IsZero() {
330				continue
331			}
332			if _, ok := installedSet[types.AgentName(name)]; !ok {
333				continue
334			}
335			out = append(out, AgentChoice{Name: name, Label: labelForAgentChoice(name, cfg)})
336		}
337		sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
338		return out
339	}
