341	// labelForAgentChoice builds the picker-visible label for an agent row.
342	func labelForAgentChoice(name string, cfg settings.ReviewConfig) string {
343		switch {
344		case len(cfg.Skills) > 0:
345			return fmt.Sprintf("%s   (%d skills configured)", name, len(cfg.Skills))
346		case cfg.Prompt != "":
347			return name + "   (prompt-only)"
348		default:
349			return name
350		}
351	}
