353	// computeLaunchableEligible returns the subset of ComputeEligibleConfigured
354	// that also have a non-nil AgentReviewer (i.e., are launchable by the CLI).
355	// Used by the dispatch fork in cmd.go to decide whether to route to the
356	// multi-agent path.
357	//
358	// reviewerFor is deps.ReviewerFor injected at the cmd layer; it returns nil
359	// for non-launchable agents (cursor, opencode, factoryai-droid, copilot-cli).
360	func computeLaunchableEligible(
361		s *settings.EntireSettings,
362		installed []types.AgentName,
363		reviewerFor func(string) reviewtypes.AgentReviewer,
364	) []AgentChoice {
365		eligible := ComputeEligibleConfigured(s, installed)
366		out := make([]AgentChoice, 0, len(eligible))
367		for _, c := range eligible {
368			if reviewerFor(c.Name) != nil {
369				out = append(out, c)
370			}
371		}
372		return out
373	}
