375	// PromptForAgent renders the single-select agent picker shown when more than
376	// one eligible agent is configured. Returns the chosen agent name. Respects
377	// accessibility mode via newAccessibleForm.
378	func PromptForAgent(ctx context.Context, eligible []AgentChoice) (string, error) {
379		if err := ctx.Err(); err != nil {
380			return "", fmt.Errorf("agent picker: %w", err)
381		}
382		if len(eligible) == 0 {
383			return "", errors.New("no eligible agents to prompt for")
384		}
385		options := make([]huh.Option[string], 0, len(eligible))
386		for _, c := range eligible {
387			options = append(options, huh.NewOption(c.Label, c.Name))
388		}
389		picked := eligible[0].Name
390		form := newAccessibleForm(huh.NewGroup(
391			huh.NewSelect[string]().
392				Title("Which agent should run this review?").
393				Options(options...).
394				Value(&picked),
395		))
396		if err := form.RunWithContext(ctx); err != nil {
397			return "", fmt.Errorf("agent picker: %w", err)
398		}
399		return picked, nil
400	}
