402	// SelectReviewAgent picks an agent from the configured review map.
403	//
404	// If override is non-empty, returns the config for that agent or an error
405	// listing the configured alternatives. Otherwise returns the alphabetically
406	// first configured agent — deterministic but user-overridable via --agent.
407	func SelectReviewAgent(review map[string]settings.ReviewConfig, override string) (string, settings.ReviewConfig, error) {
408		if len(review) == 0 {
409			return "", settings.ReviewConfig{}, errors.New("no review config found")
410		}
411		var names []string
412		for name, cfg := range review {
413			if !cfg.IsZero() {
414				names = append(names, name)
415			}
416		}
417		if len(names) == 0 {
418			return "", settings.ReviewConfig{}, errors.New("no review config found")
419		}
420		sort.Strings(names)
421		if override != "" {
422			if cfg, ok := review[override]; ok && !cfg.IsZero() {
423				return override, cfg, nil
424			}
425			return "", settings.ReviewConfig{}, fmt.Errorf(
426				"agent %q is not configured for review; configured agents: %s",
427				override, strings.Join(names, ", "),
428			)
429		}
430		pick := names[0]
431		return pick, review[pick], nil
432	}
