434	// VerifyConfiguredSkillsInstalled is the spawn-time backstop for the
435	// silent-failure vector. For each skill in cfg.Skills, check it's either a
436	// curated built-in or returned by the agent's SkillDiscoverer; fail with a
437	// user-facing error if any skill is missing. Empty Skills (prompt-only
438	// config) short-circuits to nil — a freeform prompt has no skill list to
439	// validate against.
440	func VerifyConfiguredSkillsInstalled(ctx context.Context, ag agent.Agent, cfg settings.ReviewConfig) error {
441		if len(cfg.Skills) == 0 {
442			return nil
443		}
444		builtins := builtinNameSet(skilldiscovery.CuratedBuiltinsFor(string(ag.Name())))
445		discoveredNames := map[string]struct{}{}
446		if d, ok := ag.(agent.SkillDiscoverer); ok {
447			if skills, err := d.DiscoverReviewSkills(ctx); err == nil {
448				for _, s := range skills {
449					discoveredNames[s.Name] = struct{}{}
450				}
451			} else {
452				logging.Debug(ctx, "skill verification discovery failed",
453					slog.String("agent", string(ag.Name())), slog.String("error", err.Error()))
454			}
455		}
456		var missing []string
457		for _, s := range cfg.Skills {
458			if _, ok := builtins[s]; ok {
459				continue
460			}
461			if _, ok := discoveredNames[s]; ok {
462				continue
463			}
464			missing = append(missing, s)
465		}
466		if len(missing) == 0 {
467			return nil
468		}
469		return fmt.Errorf(
470			"configured review skill(s) not installed: %s\n"+
471				"run `entire review --edit` to reconfigure, or install the plugin and retry",
472			strings.Join(missing, ", "),
473		)
474	}
