476	// BuildReviewPickerFields composes the per-agent group fields for the
477	// review picker. Returns a slice of huh.Field in render order:
478	//
479	//	0: built-in commands (multiselect) OR note
480	//	1: installed plugin skills (multiselect) OR note
481	//	2: install hints (note with all active hint messages) — OMITTED if empty
482	//	3: additional instructions (text) — always present
483	func BuildReviewPickerFields(
484		agentName string,
485		builtins []skilldiscovery.CuratedSkill,
486		discovered []agent.DiscoveredSkill,
487		activeHints []skilldiscovery.InstallHint,
488		previousPrompt string,
489		builtinPicksOut, discoveredPicksOut *[]string,
490		promptOut *string,
491	) []huh.Field {
492		var fields []huh.Field
493	
494		if builtinPicksOut != nil && len(*builtinPicksOut) == 0 &&
495			len(builtins) == 1 && strings.TrimSpace(previousPrompt) == "" {
496			*builtinPicksOut = []string{builtins[0].Name}
497		}
498	
499		builtinPreselected := preselectedSet(builtinPicksOut)
500		discoveredPreselected := preselectedSet(discoveredPicksOut)
501	
502		if len(builtins) > 0 {
503			opts := make([]huh.Option[string], 0, len(builtins))
504			for _, b := range builtins {
505				opt := huh.NewOption(b.Name, b.Name)
506				if _, ok := builtinPreselected[b.Name]; ok {
507					opt = opt.Selected(true)
508				}
509				opts = append(opts, opt)
510			}
511			ms := huh.NewMultiSelect[string]().
512				Title("Built-in commands").
513				Options(opts...).
514				Height(len(opts) + 1)
515			if builtinPicksOut != nil {
516				ms = ms.Value(builtinPicksOut)
517			}
518			fields = append(fields, ms)
519		} else {
520			fields = append(fields, huh.NewNote().
521				Title("Built-in commands").
522				Description(fmt.Sprintf("No built-in review commands in %s.", agentName)))
523		}
524	
525		if len(discovered) > 0 {
526			opts := make([]huh.Option[string], 0, len(discovered))
527			for _, d := range discovered {
528				opt := huh.NewOption(d.Name, d.Name)
529				if _, ok := discoveredPreselected[d.Name]; ok {
530					opt = opt.Selected(true)
531				}
532				opts = append(opts, opt)
533			}
534			ms := huh.NewMultiSelect[string]().
535				Title("Installed plugin skills").
536				Options(opts...).
537				Height(len(opts) + 1)
538			if discoveredPicksOut != nil {
539				ms = ms.Value(discoveredPicksOut)
540			}
541			fields = append(fields, ms)
542		} else {
543			fields = append(fields, huh.NewNote().
544				Title("Installed plugin skills").
545				Description("No plugin review skills detected on disk."))
546		}
547	
548		if len(activeHints) > 0 {
549			var sb strings.Builder
550			for i, h := range activeHints {
551				if i > 0 {
552					sb.WriteString("\n")
553				}
554				sb.WriteString("• ")
555				sb.WriteString(h.Message)
556			}
557			fields = append(fields, huh.NewNote().
558				Title("Install more").
559				Description(sb.String()))
560		}
561	
562		text := huh.NewText().
563			Title("Additional instructions (optional)").
564			Description("Added after selected skills. If no skills are selected, this becomes the full review prompt.")
565		if promptOut != nil {
566			*promptOut = previousPrompt
567			text = text.Value(promptOut)
568		}
569		fields = append(fields, text)
570	
571		return fields
572	}
573	
574	// SplitSavedPicks partitions a flat saved-skills list into the subset that
575	// matches built-in curated commands and the subset that matches discovered
576	// plugin skills. Skill names that match neither are dropped from both — they're
577	// preserved on the settings side via MergePickerResults when they belong to a
578	// picker-unaware agent entry.
579	func SplitSavedPicks(saved []string, builtins []skilldiscovery.CuratedSkill, discovered []agent.DiscoveredSkill) ([]string, []string) {
580		builtinNames := make(map[string]struct{}, len(builtins))
581		for _, b := range builtins {
582			builtinNames[b.Name] = struct{}{}
583		}
584		discoveredNames := make(map[string]struct{}, len(discovered))
585		for _, d := range discovered {
586			discoveredNames[d.Name] = struct{}{}
587		}
588		var builtinPicks, discoveredPicks []string
589		for _, s := range saved {
590			if _, ok := builtinNames[s]; ok {
591				builtinPicks = append(builtinPicks, s)
592				continue
593			}
594			if _, ok := discoveredNames[s]; ok {
595				discoveredPicks = append(discoveredPicks, s)
596			}
597		}
598		return builtinPicks, discoveredPicks
599	}
600	
601	// preselectedSet turns a slice pointer's current contents into a lookup
602	// set for the picker's "previously-saved" pre-selection.
603	func preselectedSet(slice *[]string) map[string]struct{} {
604		if slice == nil || len(*slice) == 0 {
605			return nil
606		}
607		out := make(map[string]struct{}, len(*slice))
608		for _, s := range *slice {
609			out[s] = struct{}{}
610		}
611		return out
612	}
613	
614	func builtinNameSet(curated []skilldiscovery.CuratedSkill) map[string]struct{} {
615		set := make(map[string]struct{}, len(curated))
616		for _, c := range curated {
617			set[c.Name] = struct{}{}
618		}
619		return set
620	}
621	
622	// filterOutBuiltinCollisions drops any discovered skill whose name collides
623	// with a curated built-in. Built-in wins because it carries a richer,
624	// hand-authored description.
625	func filterOutBuiltinCollisions(discovered []agent.DiscoveredSkill, builtins map[string]struct{}) []agent.DiscoveredSkill {
626		if len(discovered) == 0 || len(builtins) == 0 {
627			return discovered
628		}
629		out := make([]agent.DiscoveredSkill, 0, len(discovered))
630		for _, d := range discovered {
631			if _, clash := builtins[d.Name]; clash {
632				continue
633			}
634			out = append(out, d)
635		}
636		return out
637	}
638	
639	func dedupeStrings(xs []string) []string {
640		if len(xs) == 0 {
641			return xs
642		}
643		seen := make(map[string]struct{}, len(xs))
644		out := make([]string, 0, len(xs))
645		for _, x := range xs {
646			if _, ok := seen[x]; ok {
647				continue
648			}
649			seen[x] = struct{}{}
650			out = append(out, x)
651		}
652		return out
653	}
