132		cfg := reviewtypes.RunConfig{
133			Skills:      []string{"/test"},
134			StartingSHA: "abc123",
135		}
136	
137		ctx, cancel := context.WithCancel(context.Background())
138		defer cancel()
139	
140		// Construction (NewReviewer) MUST NOT touch PATH. Start may or may
141		// not error depending on whether the OS-level cmd.Start tries to
142		// resolve before fork — that's fine. The contract is just "no panic
143		// and no upfront LookPath call".
144		proc, err := r.Start(ctx, cfg)
