  ```go
  package codex

  import (
      "strings"

      reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
  )

  // composeNativeReviewPrompt builds the stdin payload for `codex exec review -`.
  // It mirrors review.ComposeReviewPrompt but drops the two pieces that
  // `codex exec review` now handles natively:
  //
  //  1. The `/review` skill invocation — the subcommand IS the review.
  //  2. The explicit "Scope: ..." clause — `--base` / `--uncommitted` flags
  //     carry scope authoritatively.
  //
  // PromptOverride bypasses composition for callers that need verbatim control.
  func composeNativeReviewPrompt(cfg reviewtypes.RunConfig) string {
      if cfg.PromptOverride != "" {
          return cfg.PromptOverride
      }

      var sections []string

      // Skills, minus /review (handled by `exec review` subcommand).
      filtered := filterOutBuiltinReview(cfg.Skills)
      if len(filtered) > 0 {
          sections = append(sections, strings.Join(filtered, "\n"))
      }

      if trimmed := strings.TrimRight(cfg.AlwaysPrompt, "\n\r "); trimmed != "" {
          sections = append(sections, trimmed)
      }
      if trimmed := strings.TrimRight(cfg.PerRunPrompt, "\n\r "); trimmed != "" {
          sections = append(sections, trimmed)
      }
      // NB: no explicit Scope clause here — codex `--base` / `--uncommitted` flags
      // are the authoritative source. The redundant clause confused codex's
      // exec-mode reasoning loop and was a contributor to the 2-5x speed gap.

      if trimmed := strings.TrimRight(cfg.CheckpointContext, "\n\r "); trimmed != "" {
          sections = append(sections, trimmed)
      }
      return strings.Join(sections, "\n\n")
  }

  // filterOutBuiltinReview removes the literal `/review` token from a skills
  // list. Other skill invocations pass through verbatim — codex picker only
  // offers `/review` today (DiscoverReviewSkills is stubbed), so this is a
  // future-compat hedge for when plugin discovery lands.
  func filterOutBuiltinReview(skills []string) []string {
      out := make([]string, 0, len(skills))
      for _, s := range skills {
          if s == "/review" {
              continue
          }
          out = append(out, s)
      }
      return out
  }
  ```

