  // did not accept a [PROMPT] argument.
  func NewReviewer() *reviewtypes.ReviewerTemplate {
      return &reviewtypes.ReviewerTemplate{
          AgentName: "codex",
          BuildCmd:  buildCodexReviewCmd,
          Parser:    parseCodexOutput,
      }
  }

  // buildCodexReviewCmd builds the exec.Cmd for a codex review run via codex's
  // native `exec review` subcommand. Exposed at package level for test
  // inspection of argv, stdin, and env.
  func buildCodexReviewCmd(ctx context.Context, cfg reviewtypes.RunConfig) *exec.Cmd {
      args := []string{codexExecCommand, "review"}
      if cfg.ScopeBaseRef != "" {
          args = append(args, "--base", cfg.ScopeBaseRef)
      }
      args = append(args, "--uncommitted", "--json", "--skip-git-repo-check", "-")

      prompt := composeNativeReviewPrompt(cfg)
      cmd := exec.CommandContext(ctx, "codex", args...)
      cmd.Stdin = strings.NewReader(prompt)
      cmd.Env = review.AppendReviewEnv(os.Environ(), "codex", cfg, prompt)
      return cmd
  }

  const codexExecCommand = "exec"
