	}
}

// Pins the documented contract in composeNativeReviewPrompt's doc comment
// and the "Plugin / Skill Invocation" section of codex/AGENT.md: codex's
// actual plugin invocation (`@plugin-name`) and bundled-skill invocation
// (`$skill-name`) forms must pass through verbatim so codex can resolve
// them at runtime. Without this test, a naive future change to
// filterOutBuiltinReview that filters non-`/`-prefixed entries would not
// regress any existing test.
func TestComposeNativeReviewPrompt_PreservesCodexInvocationForms(t *testing.T) {
	t.Parallel()
	cfg := reviewtypes.RunConfig{Skills: []string{"/review", "@codex-review-pack", "$thorough-review"}}
	got := composeNativeReviewPrompt(cfg)
	if !strings.Contains(got, "@codex-review-pack") {
		t.Errorf("@plugin invocation must pass through verbatim: %q", got)
	}
	if !strings.Contains(got, "$thorough-review") {
		t.Errorf("$skill invocation must pass through verbatim: %q", got)
	}
	if strings.Contains(got, "/review") {
		t.Errorf("/review must still be filtered: %q", got)
	}
}

// Boundary: an empty RunConfig must compose to the empty string. Codex's
// curated review prompt then drives the entire review with no additional
// instructions from entire. Pins this to prevent accidental regressions
// (e.g. emitting a header line when sections is empty).
func TestComposeNativeReviewPrompt_EmptyConfigReturnsEmpty(t *testing.T) {
	t.Parallel()
	got := composeNativeReviewPrompt(reviewtypes.RunConfig{})
	if got != "" {
		t.Errorf("empty RunConfig must compose to \"\", got %q", got)
	}
}
